// The character builder: one person, edited section by section with a live preview card.
// Used by the story setup wizard (you, your family, your people) and by Character Studio.
// Anything left on "auto" is generated by the server from the archetype with natural variation.
import React, { useEffect, useMemo, useState } from "react";
import { api } from "../api";
import type { Look } from "../phone/api";
import { Portrait, fullLook } from "../phone/art";
import LookPicker from "../phone/art/LookPicker";
import { cx } from "../ui";
import "./builder.css";

export type Gender = "f" | "m" | "nb";
export interface RelSpec { to: string; type: string; strength?: number }
export interface Person {
  key?: string;
  first: string;
  last?: string;
  gender: Gender | "";
  pronouns?: string;
  attracted_to?: Gender[];
  grade?: number;
  role?: "student" | "staff";
  title?: string;
  role_label?: string;
  coach_of?: string;
  archetype?: string;
  traits?: Record<string, number>;
  aptitudes?: Record<string, number>;
  motives?: Record<string, number>;
  interests?: Record<string, number>;
  skills?: Record<string, number>;
  body?: { height_in?: number; build?: string };
  positions?: Record<string, string>;
  jersey?: number | null;
  birthday?: [number, number] | null;
  color?: string;
  bio?: string;
  relationships?: RelSpec[];
  path?: { kind?: "college" | "work"; college?: string; sport?: string | null } | null;
  look?: Partial<Look>;
  // siblings
  twin_of?: string;
  strength?: number;
  // cast
  household?: string;
  template?: string;
}
export interface Target { key: string; name: string; color?: string }
export type BuilderMode = "protagonist" | "sibling" | "cast" | "studio";

export const TRAITS = ["sociability", "confidence", "discipline", "ambition", "impulsivity", "empathy", "competitiveness", "curiosity", "volatility", "loyalty"];
export const APTS = ["athletic", "academic", "creativity", "technical", "charisma"];
export const MOTIVES = ["achievement", "approval", "belonging", "pleasure", "altruism", "mastery"];
export const SPORTS = ["football", "basketball", "soccer", "baseball", "softball"];
/** Boys play football, basketball, soccer and baseball; girls play basketball, soccer and softball (nonbinary: any). */
export const ONLY: Record<string, string> = { football: "m", baseball: "m", softball: "f" };
export function sportsFor(gender?: string) {
  return SPORTS.filter((s) => !ONLY[s] || !(gender === "m" || gender === "f") || ONLY[s] === gender);
}
/** High school teams a coach can run: [team id, label]. */
export const TEAMS: [string, string][] = [["football", "Football"], ["basketball", "Boys basketball"], ["basketball_girls", "Girls basketball"],
  ["soccer", "Boys soccer"], ["soccer_girls", "Girls soccer"], ["baseball", "Baseball"], ["softball", "Softball"]];
export const GRADE_LABEL: Record<number, string> = { 6: "6th grade", 7: "7th grade", 8: "8th grade", 9: "Freshman", 10: "Sophomore", 11: "Junior", 12: "Senior" };
export const COLORS = ["#57d9c3", "#6bb6ff", "#9b8cff", "#c08cff", "#ff8fc7", "#ff6b81", "#ff9a62", "#ffb547", "#f4d35e", "#b5e48c", "#66d98f", "#4fc3f7"];

export const TRAIT_WORDS: Record<string, [string, string]> = {
  sociability: ["outgoing", "reserved"], confidence: ["confident", "self-doubting"], discipline: ["disciplined", "easily distracted"],
  ambition: ["ambitious", "easygoing about the future"], impulsivity: ["impulsive", "careful"], empathy: ["caring", "blunt"],
  competitiveness: ["competitive", "laid-back"], curiosity: ["curious", "set in their ways"], volatility: ["hot-headed", "even-keeled"],
  loyalty: ["loyal", "independent"],
};
export const MOTIVE_WORDS: Record<string, string> = {
  achievement: "winning and achieving", approval: "being liked and noticed", belonging: "being close to their people",
  pleasure: "having a good time", altruism: "helping other people", mastery: "getting really good at things",
};
const MINI: Record<string, string> = { sociability: "social", confidence: "confident", discipline: "discipline", ambition: "ambition", impulsivity: "impulsive",
  empathy: "empathy", competitiveness: "compete", curiosity: "curious", volatility: "temper", loyalty: "loyal" };
export const APT_LABEL: Record<string, string> = { athletic: "Athletic", academic: "Academic", creativity: "Creative", technical: "Technical", charisma: "Charisma" };
export const ARCH_BLURB: Record<string, string> = {
  athlete: "Lives for competition and the next game.", artist: "Happiest making things nobody asked for.",
  scholar: "Grades, books and getting it right.", socialite: "Knows everyone and goes everywhere.",
  loner: "Keeps a small world and likes it that way.", rebel: "Rules are more like suggestions.",
  leader: "Runs the meeting and the group chat.", techie: "Robots, code and taking things apart.",
  performer: "Stage, spotlight, applause.", caretaker: "The one everybody calls when it goes wrong.",
  drifter: "Going with the flow, figuring it out.",
};
export const BUILD_HINT: Record<string, string> = {
  slight: "Quick and light. Receivers, wingers, guards; rough in the trenches.",
  average: "No edge either way.",
  athletic: "The all-around body. A plus almost anywhere, in every sport.",
  strong: "Power: linemen, center backs, catchers. A step slower out wide.",
};
export const SEASON: Record<string, string> = { fall: "Fall", winter: "Winter", spring: "Spring" };
export const REL_TYPES = ["best_friend", "close_friend", "friend", "acquaintance", "crush", "admirer", "mutual_crush", "dating", "ex",
  "rival", "enemy", "teammate", "neighbor", "mentor", "sibling", "twin"];

// ---------------------------------------------------------------- catalog
let catCache: any = null;
let catPromise: Promise<any> | null = null;
export function useStoryCatalog() {
  const [cat, setCat] = useState<any>(catCache);
  const [error, setError] = useState<string | null>(null);
  useEffect(() => {
    if (catCache) return;
    if (!catPromise) catPromise = api.get("/api/story/catalog").then((c) => (catCache = c));
    let live = true;
    catPromise.then((c) => live && setCat(c)).catch((e) => {
      catPromise = null;
      if (live) setError(e.message);
    });
    return () => {
      live = false;
    };
  }, []);
  return { cat, error };
}

// ---------------------------------------------------------------- helpers
export const cap = (s: string) => (s ? s[0].toUpperCase() + s.slice(1) : s);
const clamp = (x: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, x));
function gauss(mean: number, sd: number) {
  const u = 1 - Math.random();
  const v = Math.random();
  return mean + sd * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
export function archOf(cat: any, id?: string) {
  return cat?.archetypes?.find((a: any) => a.id === id) || null;
}
export function archLabel(cat: any, id?: string) {
  return archOf(cat, id)?.label || (id ? cap(id) : "Surprise me");
}
export function yearLabel(p: Person) {
  if (p.role === "staff") return p.role_label || (p.coach_of ? `${cap(p.coach_of)} coach` : "Teacher");
  return GRADE_LABEL[p.grade || 9] || `Grade ${p.grade}`;
}
export function heightLabel(h?: number) {
  if (!h) return "";
  return `${Math.floor(h / 12)}'${h % 12}"`;
}
export function displayName(p: Person, fallback = "Unnamed") {
  const n = [p.role === "staff" ? p.title : "", p.first?.trim(), p.last?.trim()].filter(Boolean).join(" ");
  return p.first?.trim() ? n : fallback;
}
/** The look a person shows in the builder: what was picked, with the rest filled in from their key or name. */
export function lookOf(p: Person): Look {
  const seed = p.key || [p.first, p.last].filter(Boolean).join(" ").trim() || "new person";
  return fullLook(p.look, seed, p.gender || null, p.role === "staff");
}
export function initialsOf(p: Person) {
  const a = (p.first || "?").trim()[0] || "?";
  const b = (p.last || "").trim()[0] || "";
  return (a + b).toUpperCase();
}
/** The value a slider shows: what the user set, else the archetype's average, else 50. */
export function shown(cat: any, p: Person, layer: "traits" | "aptitudes" | "motives", k: string): number {
  const v = p[layer]?.[k];
  if (v !== undefined && v !== null) return v;
  const a = archOf(cat, p.archetype);
  return a?.[layer]?.[k] ?? 50;
}
function shownInterest(cat: any, p: Person, k: string): number | null {
  const v = p.interests?.[k];
  if (v !== undefined) return v;
  const a = archOf(cat, p.archetype);
  if (!a) return null;
  if (SPORTS.includes(k) && a.interests?.sport) return null;
  return a.interests?.[k] ?? null;
}
export function autoSkill(cat: any, p: Person, s: any) {
  const a = shown(cat, p, "aptitudes", s.aptitude);
  const iv = shownInterest(cat, p, s.id) ?? 0;
  return Math.round(clamp(a * 0.3 + iv * 0.28 + ((p.grade || 9) - 9) * 2.5, 0, 70));
}
export function interestLabel(cat: any, k: string) {
  const s = cat?.skills?.find((x: any) => x.id === k);
  if (s) return s.label;
  const h = cat?.hobbies?.find((x: any) => x.id === k);
  return h ? cap(h.label) : cap(k.replace(/_/g, " "));
}
function listJoin(xs: string[]) {
  if (xs.length <= 1) return xs.join("");
  return xs.slice(0, -1).join(", ") + " and " + xs[xs.length - 1];
}
/** A one or two line "who they are", built from the sliders. */
export function summaryLine(cat: any, p: Person) {
  if (!cat) return "";
  const anyTraits = Object.keys(p.traits || {}).length > 0;
  if (!anyTraits && !p.archetype) return p.role === "staff" ? "Personality left to chance." : "Personality left to chance: pick a type or move a few sliders to shape them.";
  const vals = TRAITS.map((k) => [k, shown(cat, p, "traits", k)] as [string, number]);
  const highs = vals.filter(([, v]) => v >= 66).sort((a, b) => b[1] - a[1]).slice(0, 2).map(([k]) => TRAIT_WORDS[k][0]);
  const lows = vals.filter(([, v]) => v <= 34).sort((a, b) => a[1] - b[1]).slice(0, 1).map(([k]) => TRAIT_WORDS[k][1]);
  const words = [...highs, ...lows];
  const first = words.length ? cap(listJoin(words)) + "." : "Pretty balanced, no sharp edges.";
  if (p.role === "staff") return first;
  const mots = MOTIVES.map((k) => [k, shown(cat, p, "motives", k)] as [string, number]).sort((a, b) => b[1] - a[1]);
  const mot = mots[0][1] >= 58 && mots[0][1] - mots[1][1] >= 3 ? ` Driven by ${MOTIVE_WORDS[mots[0][0]]}.` : "";
  const ints = Object.entries(p.interests || {}).filter(([, v]) => v >= 50).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([k]) => interestLabel(cat, k).toLowerCase());
  return `${first}${mot}${ints.length ? ` Into ${listJoin(ints)}.` : ""}`;
}
/** How much this body helps at this position compared with the sport's other positions. */
export function positionFit(sport: string, pos: string, h = 68, build = "average") {
  if (sport === "football") {
    if (pos === "OL" || pos === "DL") return ({ strong: 7, athletic: 2, average: -2, slight: -10 } as any)[build] || 0;
    if (["WR", "DB", "RB"].includes(pos)) return ({ slight: 3, athletic: 3, strong: -2 } as any)[build] || 0;
    return 0;
  }
  if (sport === "basketball") return pos === "C" || pos === "PF" ? (h - 74) * 0.5 + (h - 72) * 0.6 : pos === "PG" ? (72 - h) * 0.3 : 0;
  if (sport === "baseball" && pos === "P") return (h - 70) * 0.4;
  if (sport === "softball" && pos === "P") return (h - 65) * 0.4;
  if (sport === "soccer") {
    const b = ({ slight: 1, average: 0, athletic: 4, strong: 2 } as any)[build] || 0;
    if (pos === "GK") return b + Math.max(-4, Math.min(5, (h - 69) * 0.6));
    if (pos === "CB") return b + (({ strong: 3, slight: -4 } as any)[build] || 0);
    return b;
  }
  return 0;
}
function fitTag(b: number): [string, string] | null {
  if (b >= 5) return ["great fit", "good"];
  if (b >= 2) return ["good fit", "accent"];
  if (b <= -4) return ["tough fit", "bad"];
  return null;
}
export function randomName(cat: any, gender: string, used: Set<string> = new Set()) {
  const pool = cat?.names?.[gender === "f" ? "female" : gender === "m" ? "male" : "nonbinary"] || ["Alex"];
  const free = pool.filter((n: string) => !used.has(n));
  const xs = free.length ? free : pool;
  return xs[Math.floor(Math.random() * xs.length)];
}
export function randomLast(cat: any) {
  const pool = cat?.names?.last || ["Smith"];
  return pool[Math.floor(Math.random() * pool.length)];
}

// Relationship wording, always from THIS person's point of view.
const youish = (t: string) => t.toLowerCase() === "you";
export function relOption(type: string, T: string) {
  const t = T;
  const map: Record<string, string> = {
    best_friend: `Best friends with ${t}`, close_friend: `Close friends with ${t}`, friend: `Friends with ${t}`,
    acquaintance: `Knows ${t} a little`, crush: `Has a crush on ${t}`,
    admirer: `${cap(t)} ${youish(t) ? "have" : "has"} a crush on them`, mutual_crush: `${cap(t)} and they like each other`,
    dating: `Dating ${t}`, ex: `Used to date ${t}`, rival: `Rivals with ${t}`, enemy: `Can't stand ${t}`,
    teammate: `Grew up on the same teams as ${t}`, neighbor: `Neighbors with ${t}`, mentor: `Looks up to ${t}`,
    sibling: `Sibling of ${t}`, twin: `Twin of ${t}`,
  };
  return map[type] || type;
}
export function relSentence(type: string, X: string, T: string) {
  const has = (s: string) => (youish(s) ? "have" : "has");
  const looks = (s: string) => (youish(s) ? "look" : "looks");
  const pair = `${cap(X)} and ${T}`;
  const map: Record<string, string> = {
    best_friend: `${pair} are best friends`, close_friend: `${pair} are close friends`, friend: `${pair} are friends`,
    acquaintance: `${pair} know each other a little`, crush: `${cap(X)} ${has(X)} a crush on ${T}`,
    admirer: `${cap(T)} ${has(T)} a crush on ${X}`, mutual_crush: `${pair} like each other`, dating: `${pair} are dating`,
    ex: `${pair} used to date`, rival: `${pair} are rivals`, enemy: `${pair} can't stand each other`,
    teammate: `${pair} grew up playing on the same teams`, neighbor: `${pair} are neighbors`, mentor: `${cap(X)} ${looks(X)} up to ${T}`,
    sibling: `${pair} are siblings`, twin: `${pair} are twins`,
  };
  return map[type] || type;
}
export function strengthWords(v: number) {
  if (!v) return "";
  if (v <= -25) return "much colder than that usually means";
  if (v < 0) return "a little cooler than usual";
  if (v >= 25) return "even closer than that usually means";
  return "a little warmer than usual";
}

/** Which builder section an API validation message belongs to. */
export function sectionForError(msg: string) {
  if (/\.look/.test(msg)) return "look";
  if (/traits/.test(msg)) return "personality";
  if (/aptitudes/.test(msg)) return "talent";
  if (/motives/.test(msg)) return "drives";
  if (/interests|skills/.test(msg)) return "interests";
  if (/body|position|jersey/.test(msg)) return "athlete";
  if (/relationships/.test(msg)) return "relationships";
  if (/archetype/.test(msg)) return "start";
  if (/\.path/.test(msg)) return "future";
  return "basics";
}
export function friendlyError(msg: string) {
  return msg.replace(/^[.:]\s*/, "").replace(/\b(traits|aptitudes|motives|interests|skills|body|positions)\./g, "").replace(/_/g, " ");
}

const round = (o?: Record<string, number>) => {
  if (!o) return undefined;
  const out: Record<string, number> = {};
  for (const [k, v] of Object.entries(o)) if (v !== undefined && v !== null && !Number.isNaN(v)) out[k] = Math.round(v);
  return Object.keys(out).length ? out : undefined;
};
/** Turn a builder person into the API's person spec, leaving out everything blank. */
export function cleanPerson(p: Person, kind: BuilderMode): any {
  const o: any = { first: (p.first || "").trim(), gender: p.gender };
  const staff = p.role === "staff" && (kind === "cast" || kind === "studio");
  if (p.last?.trim()) o.last = p.last.trim();
  if (p.pronouns?.trim()) o.pronouns = p.pronouns.trim();
  if (p.archetype) o.archetype = p.archetype;
  const tr = round(p.traits);
  if (tr) o.traits = tr;
  if (p.color) o.color = p.color;
  if (p.bio?.trim()) o.bio = p.bio.trim();
  const look = Object.fromEntries(Object.entries(p.look || {}).filter(([, v]) => v !== undefined && v !== null && v !== ""));
  if (Object.keys(look).length) o.look = look;
  if (p.birthday && p.birthday[0] && p.birthday[1]) o.birthday = [Number(p.birthday[0]), Number(p.birthday[1])];
  if (staff) {
    o.role = "staff";
    if (p.title?.trim()) o.title = p.title.trim();
    if (p.role_label?.trim()) o.role_label = p.role_label.trim();
    if (p.coach_of) o.coach_of = p.coach_of;
  } else {
    o.grade = Number(p.grade || 9);
    if (p.attracted_to?.length) o.attracted_to = p.attracted_to;
    for (const layer of ["aptitudes", "motives", "interests", "skills"] as const) {
      const r = round(p[layer]);
      if (r) o[layer] = r;
    }
    const body: any = {};
    if (p.body?.height_in) body.height_in = Math.round(p.body.height_in);
    if (p.body?.build) body.build = p.body.build;
    if (Object.keys(body).length) o.body = body;
    const pos = Object.fromEntries(Object.entries(p.positions || {}).filter(([, v]) => v));
    if (Object.keys(pos).length) o.positions = pos;
    if (p.jersey !== undefined && p.jersey !== null && String(p.jersey) !== "") o.jersey = Number(p.jersey);
  }
  if (!staff && kind !== "protagonist" && p.path) {
    if (p.path.kind === "work") o.path = { kind: "work" };
    else if (p.path.college) o.path = p.path.sport ? { college: p.path.college, sport: p.path.sport } : { college: p.path.college };
  }
  const rels = (p.relationships || []).filter((r) => r.to && r.type).map((r) => (r.strength ? { to: r.to, type: r.type, strength: Math.round(r.strength) } : { to: r.to, type: r.type }));
  if (rels.length) o.relationships = rels;
  if (p.key) o.key = p.key;
  if (kind === "sibling") {
    if (p.twin_of) o.twin_of = p.twin_of;
    if (p.strength) o.strength = Math.round(p.strength);
  }
  if (kind === "cast" && p.household && !staff) o.household = p.household;
  return o;
}

/** Fill a person's sliders with plausible random values around their archetype. */
export function randomizePerson(cat: any, p: Person, layers: string[] = ["traits", "aptitudes", "motives", "interests"]): Person {
  const a = archOf(cat, p.archetype);
  const out: Person = { ...p };
  const draw = (mean: number, sd = 12) => Math.round(clamp(gauss(mean, sd), 5, 95));
  if (layers.includes("traits")) out.traits = Object.fromEntries(TRAITS.map((k) => [k, draw(a?.traits?.[k] ?? 50, a ? 12 : 18)]));
  if (layers.includes("aptitudes")) out.aptitudes = Object.fromEntries(APTS.map((k) => [k, draw(a?.aptitudes?.[k] ?? 50, a ? 11 : 16)]));
  if (layers.includes("motives")) out.motives = Object.fromEntries(MOTIVES.map((k) => [k, draw(a?.motives?.[k] ?? 50, a ? 12 : 16)]));
  if (layers.includes("interests") && cat) {
    const ints: Record<string, number> = {};
    const src: Record<string, number> = { ...(a?.interests || {}) };
    if (src.sport) {
      const pool = sportsFor(p.gender);
      const s = pool[Math.floor(Math.random() * pool.length)];
      src[s] = src.sport;
      delete src.sport;
    }
    for (const [k, v] of Object.entries(src)) ints[k] = draw(v as number, 10);
    // keep any sport the person already plays
    for (const s of SPORTS) if (p.positions?.[s] || (p.interests?.[s] ?? 0) >= 40) ints[s] = Math.max(ints[s] || 0, p.interests?.[s] ?? 80);
    out.interests = ints;
  }
  return out;
}

// ---------------------------------------------------------------- small UI
export function Seg({ value, options, onChange, small }: { value: any; options: [any, React.ReactNode][]; onChange: (v: any) => void; small?: boolean }) {
  return (
    <div className={cx("cb-seg", small && "small")}>
      {options.map(([v, l]) => (
        <button key={String(v)} type="button" className={cx(v === value && "on")} onClick={() => onChange(v)}>{l}</button>
      ))}
    </div>
  );
}

export function PersonAvatar({ p, size = 40, glow }: { p: Person; size?: number; glow?: boolean }) {
  const c = p.color || "#9aa1c4";
  return (
    <div className={cx("cb-pav", glow && "glow")} style={{ width: size, height: size, background: "none", boxShadow: glow ? `0 0 0 3px var(--bg), 0 0 0 5px ${c}, 0 0 28px -4px ${c}` : undefined }}
      title={displayName(p, initialsOf(p))}>
      <Portrait size={size} look={lookOf(p)} color={c} name={displayName(p, "someone")} />
    </div>
  );
}

function Field({ label, hint, children, wide, required }: any) {
  return (
    <div className={cx("cb-field", wide && "wide")}>
      <div className="cb-field-l">{label}{required && <span className="req">*</span>}</div>
      {children}
      {hint && <div className="hint">{hint}</div>}
    </div>
  );
}

export function PreviewCard({ p, cat, mode, extra }: { p: Person; cat: any; mode: BuilderMode; extra?: React.ReactNode }) {
  const staff = p.role === "staff";
  const pos = SPORTS.filter((s) => p.positions?.[s]).map((s) => p.positions![s]);
  return (
    <div className="cb-card" style={{ ["--c" as any]: p.color || "#9aa1c4" }}>
      <div className="cb-card-top">
        <div className="cb-pav glow" style={{ width: 84, height: 84, background: "none", boxShadow: `0 0 0 3px var(--bg), 0 0 0 5px ${p.color || "#9aa1c4"}, 0 0 28px -4px ${p.color || "#9aa1c4"}` }}>
          <Portrait size={84} look={lookOf(p)} color={p.color || "#9aa1c4"} mood="happy" name={displayName(p, "someone")} />
        </div>
        {!staff && p.jersey !== undefined && p.jersey !== null && String(p.jersey) !== "" && <div className="cb-jersey">#{p.jersey}</div>}
      </div>
      <div className="cb-card-name">{displayName(p, mode === "protagonist" ? "You" : "New person")}</div>
      <div className="cb-card-sub">{yearLabel(p)}{!staff && <> · {archLabel(cat, p.archetype)}</>}{p.pronouns ? ` · ${p.pronouns}` : ""}</div>
      {!staff && (p.body?.height_in || p.body?.build || pos.length > 0) && (
        <div className="cb-card-chips">
          {p.body?.height_in && <span>{heightLabel(p.body.height_in)}</span>}
          {p.body?.build && <span>{p.body.build}</span>}
          {pos.map((x, i) => <span key={i} className="pos">{x}</span>)}
        </div>
      )}
      <div className="cb-card-sum">{summaryLine(cat, p)}</div>
      {cat && (
        <div className="cb-mini">
          {TRAITS.map((k) => {
            const v = shown(cat, p, "traits", k);
            const set = p.traits?.[k] !== undefined;
            return (
              <div key={k} className="cb-mini-r" title={`${k} ${Math.round(v)}${set ? "" : " (auto)"}`}>
                <span>{MINI[k]}</span>
                <div className="cb-mini-b"><i style={{ width: `${v}%`, opacity: set ? 1 : 0.45 }} /></div>
              </div>
            );
          })}
        </div>
      )}
      {extra}
    </div>
  );
}

// ---------------------------------------------------------------- the builder
interface BuilderProps {
  value: Person;
  onChange: (p: Person) => void;
  cat: any;
  mode: BuilderMode;
  people?: Target[];
  errors?: string[];
  section?: string;
  onSection?: (s: string) => void;
  selfName?: string;
  sideExtra?: React.ReactNode;
}

export default function CharacterBuilder({ value: p, onChange, cat, mode, people = [], errors = [], section, onSection, sideExtra }: BuilderProps) {
  const [own, setOwn] = useState("basics");
  const sec = section || own;
  const setSec = (s: string) => (onSection ? onSection(s) : setOwn(s));
  const staff = p.role === "staff";
  const sections: [string, string][] = staff
    ? [["basics", "Basics"], ["look", "Look"], ["personality", "Personality"], ["relationships", "Relationships"]]
    : [["basics", "Basics"], ["look", "Look"], ["start", "Starting point"], ["personality", "Personality"], ["talent", "Talent"], ["drives", "What drives them"],
       ["interests", "Interests & skills"], ["athlete", "Athlete"], ["relationships", "Relationships"],
       ...(mode === "protagonist" ? [] : [["future", "After high school"] as [string, string]])];
  const ids = sections.map((s) => s[0]);
  const cur = ids.includes(sec) ? sec : "basics";
  const errBySec = useMemo(() => {
    const m: Record<string, string[]> = {};
    for (const e of errors) (m[sectionForError(e)] = m[sectionForError(e)] || []).push(e);
    return m;
  }, [errors]);
  if (!cat) return <div className="loading">Loading the builder...</div>;
  const set = (patch: Partial<Person>) => onChange({ ...p, ...patch });
  const edited = (s: string) => {
    if (s === "personality") return !!Object.keys(p.traits || {}).length;
    if (s === "talent") return !!Object.keys(p.aptitudes || {}).length;
    if (s === "drives") return !!Object.keys(p.motives || {}).length;
    if (s === "interests") return !!Object.keys(p.interests || {}).length || !!Object.keys(p.skills || {}).length;
    if (s === "athlete") return !!(p.body?.height_in || p.body?.build || Object.keys(p.positions || {}).length || p.jersey);
    if (s === "relationships") return !!(p.relationships || []).length;
    if (s === "start") return !!p.archetype;
    if (s === "future") return !!p.path;
    if (s === "look") return !!Object.keys(p.look || {}).length;
    if (s === "basics") return !!(p.first?.trim() && p.gender);
    return false;
  };
  const idx = ids.indexOf(cur);
  const you = mode === "protagonist";
  const X = you ? "you" : (p.first?.trim() || "they");
  const intro: Record<string, string> = {
    basics: you ? "Who you are on the first day of school." : "The basics. Only a first name and gender are required.",
    look: you ? "How you look in the story: face, hair, skin. Leave it on auto and one is picked for you." : `How ${X} looks in the story. Leave it on auto and a look is picked for ${X === "they" ? "them" : X}.`,
    start: "Pick a type. It sets every slider you leave on auto, so this alone gets you a believable person. You can still change anything.",
    personality: "Stable tendencies. They change very slowly over the years, and they shape every choice.",
    talent: "Natural aptitude: how fast skills grow and how high they can go.",
    drives: "What they want out of life. These weigh on every decision.",
    interests: "What they're into. Interests pull them toward clubs, teams and the people who share them.",
    athlete: "Body, number and positions. Coaches pick rosters and starters from skill, talent, fitness and fit.",
    future: `Leave it to play out, or decide now where ${X} ends up after graduation. A set path is a promise: the offer or the acceptance shows up senior spring and ${X} takes it.`,
    relationships: you ? "You can also set these from each person's side in the next steps." : `How ${X} knows the people in this story, from ${X === "they" ? "their" : X + "'s"} point of view.`,
  };
  return (
    <div className="cb">
      <aside className="cb-side">
        <PreviewCard p={p} cat={cat} mode={mode} extra={sideExtra} />
        <nav className="cb-nav">
          {sections.map(([k, l], i) => (
            <button key={k} type="button" className={cx("cb-nav-i", k === cur && "on")} onClick={() => setSec(k)}>
              <span className={cx("cb-step", edited(k) && "done")}>{edited(k) ? "✓" : i + 1}</span>
              <span className="cb-nav-l">{l}</span>
              {errBySec[k] && <span className="cb-err-dot" title={errBySec[k].join("\n")}>!</span>}
            </button>
          ))}
        </nav>
      </aside>
      <div className="cb-main">
        <div className="cb-sec-h">
          <h2>{sections[idx][1]}</h2>
          <p>{intro[cur]}</p>
        </div>
        {errBySec[cur] && <div className="errorbox">{errBySec[cur].map(friendlyError).join("\n")}</div>}
        {cur === "basics" && <Basics p={p} set={set} cat={cat} mode={mode} />}
        {cur === "look" && (
          <LookPicker value={p.look} base={lookOf(p)} onChange={(look) => set({ look })} gender={p.gender || undefined}
            color={p.color || "#9aa1c4"} adult={staff} name={displayName(p, "someone")} />
        )}
        {cur === "start" && <Start p={p} onChange={onChange} cat={cat} />}
        {cur === "personality" && <SliderSection p={p} onChange={onChange} cat={cat} layer="traits" keys={TRAITS} />}
        {cur === "talent" && <SliderSection p={p} onChange={onChange} cat={cat} layer="aptitudes" keys={APTS} />}
        {cur === "drives" && <SliderSection p={p} onChange={onChange} cat={cat} layer="motives" keys={MOTIVES} />}
        {cur === "interests" && <Interests p={p} onChange={onChange} cat={cat} />}
        {cur === "athlete" && <Athlete p={p} onChange={onChange} cat={cat} />}
        {cur === "relationships" && <Relationships p={p} set={set} people={people} mode={mode} />}
        {cur === "future" && <Future p={p} set={set} cat={cat} />}
        <div className="cb-sec-f">
          <button type="button" disabled={idx === 0} onClick={() => setSec(ids[idx - 1])}>← {idx > 0 ? sections[idx - 1][1] : ""}</button>
          <span className="spacer" />
          {idx < ids.length - 1 && <button type="button" className="cb-link" onClick={() => setSec(ids[idx + 1])}>{sections[idx + 1][1]} →</button>}
        </div>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------- sections

function Future({ p, set, cat }: { p: Person; set: (x: Partial<Person>) => void; cat: any }) {
  const cols: any[] = cat.colleges || [];
  const path = p.path || null;
  const mode = !path ? "auto" : path.kind === "work" ? "work" : path.sport ? "sport" : "student";
  const col = cols.find((c) => c.id === path?.college);
  const big = cols.filter((c) => !c.local);
  const local = cols.filter((c) => c.local);
  const pickCollege = (id: string) => {
    const c = cols.find((x) => x.id === id);
    let sport = mode === "sport" ? path?.sport || c?.sports?.[0] || null : null;
    if (sport && c && !c.sports.includes(sport)) sport = c.sports[0] || null;
    set({ path: { kind: "college", college: id, sport } });
  };
  const card = (c: any) => (
    <button key={c.id} type="button" className={cx("cb-arch", path?.college === c.id && "on")} onClick={() => pickCollege(c.id)}>
      <div className="cb-arch-h"><b>{c.short}</b> <span className="hint">{c.conference || (c.tier === "CC" ? "community college" : c.tier)}</span></div>
      <div className="hint">{c.mascot ? `${c.mascot} · ` : ""}{c.location}</div>
      {mode === "sport" && c.sports.length > 0 && (
        <div className="hint">{c.sports.map((s: string) => `${cap(s)} ${c.programs[s]}`).join(" · ")}</div>
      )}
    </button>
  );
  return (
    <div className="cb-fields">
      <Field label="Their path" wide>
        <Seg value={mode} onChange={(v) => {
          if (v === "auto") set({ path: null });
          else if (v === "work") set({ path: { kind: "work" } });
          else if (v === "student") set({ path: { kind: "college", college: path?.college || "uconn", sport: null } });
          else {
            const c = cols.find((x) => x.id === (path?.college || "uconn"));
            set({ path: { kind: "college", college: c?.id || "uconn", sport: c?.sports?.[0] || "basketball" } });
          }
        }} options={[["auto", "Let it play out"], ["sport", "Play a sport in college"], ["student", "College as a student"], ["work", "Stay in town and work"]]} />
      </Field>
      {(mode === "sport" || mode === "student") && (
        <>
          <Field label="College" wide hint={mode === "sport" ? "Numbers are how strong each program is. Stronger programs want better players." : undefined}>
            <div className="cb-arch-grid">{big.map(card)}</div>
          </Field>
          {mode === "student" && local.length > 0 && (
            <Field label="Close to home" wide><div className="cb-arch-grid">{local.map(card)}</div></Field>
          )}
          {mode === "sport" && col && (
            <Field label="Sport" wide>
              <Seg value={path?.sport} onChange={(v) => set({ path: { kind: "college", college: col.id, sport: v } })}
                options={col.sports.map((s: string) => [s, cap(s)])} />
            </Field>
          )}
          {col && (
            <div className="callout" style={{ gridColumn: "1 / -1" }}>
              {mode === "sport"
                ? <>{p.first || "They"} will get a {path?.sport === "football" || path?.sport === "basketball" ? "full" : "partial"} scholarship offer from {col.short} senior spring and commit. We'll make sure {p.first || "they"} {path?.sport ? `plays ${path.sport} in high school and is good enough to be recruited` : "is ready"}.</>
                : <>{p.first || "They"} will get into {col.short} and go there after graduation.</>}
            </div>
          )}
        </>
      )}
      {mode === "work" && <div className="callout" style={{ gridColumn: "1 / -1" }}>{p.first || "They"} will skip college, stay home and start working full time after graduation.</div>}
    </div>
  );
}
function Basics({ p, set, cat, mode }: { p: Person; set: (x: Partial<Person>) => void; cat: any; mode: BuilderMode }) {
  const staff = p.role === "staff";
  const canStaff = mode === "cast" || mode === "studio";
  const toggleAttr = (g: Gender) => {
    const cur = new Set(p.attracted_to || []);
    if (cur.has(g)) cur.delete(g);
    else cur.add(g);
    set({ attracted_to: Array.from(cur) as Gender[] });
  };
  const bd = p.birthday || [0, 0];
  return (
    <div className="cb-fields">
      {canStaff && (
        <Field label="Who are they?" wide>
          <Seg value={staff ? "staff" : "student"} options={[["student", "A student"], ["staff", "A teacher or coach"]]}
            onChange={(v) => set(v === "staff" ? { role: "staff", title: p.title || "Coach" } : { role: "student" })} />
        </Field>
      )}
      <Field label="First name" required>
        <div className="cb-inline">
          <input type="text" value={p.first} maxLength={30} placeholder={mode === "protagonist" ? "Your first name" : "First name"} onChange={(e) => set({ first: e.target.value })} />
          <button type="button" className="small" title="Pick a random name" onClick={() => set({ first: randomName(cat, p.gender || "m") })}>🎲</button>
        </div>
      </Field>
      <Field label="Last name" hint={mode === "sibling" ? "Leave blank to use the family name" : mode === "protagonist" ? "Also used as your family's name" : "Leave blank for a generated one"}>
        <div className="cb-inline">
          <input type="text" value={p.last || ""} maxLength={30} placeholder="Last name" onChange={(e) => set({ last: e.target.value })} />
          {mode !== "sibling" && <button type="button" className="small" title="Pick a random last name" onClick={() => set({ last: randomLast(cat) })}>🎲</button>}
        </div>
      </Field>
      <Field label="Gender" required>
        <Seg value={p.gender} options={[["m", "Male"], ["f", "Female"], ["nb", "Nonbinary"]]} onChange={(v) => set({ gender: v })} />
      </Field>
      <Field label="Pronouns" hint="Optional. Set automatically from gender if blank.">
        <input type="text" value={p.pronouns || ""} maxLength={20} placeholder={p.gender === "f" ? "she/her" : p.gender === "m" ? "he/him" : "they/them"} onChange={(e) => set({ pronouns: e.target.value })} />
      </Field>
      {!staff && (
        <Field label={mode === "protagonist" ? "Grade on the first day" : "Grade"} wide hint={mode === "protagonist" ? "The story starts on the first day of the school year. Freshman gives you all four years." : undefined}>
          <Seg value={p.grade || 9} options={(mode === "protagonist" ? [9, 10, 11, 12] : [9, 10, 11, 12, 8, 7, 6]).map((g) => [g, <span key={g}><b>{g}</b> {g < 9 ? `starts in ${9 - g}y` : GRADE_LABEL[g]}</span>])} onChange={(v) => set({ grade: v })} />
        </Field>
      )}
      {staff && (
        <>
          <Field label="Title">
            <select value={p.title || "Coach"} onChange={(e) => set({ title: e.target.value })}>
              {["Coach", "Mr.", "Ms.", "Mrs.", "Mx.", "Dr."].map((t) => <option key={t}>{t}</option>)}
            </select>
          </Field>
          <Field label="Coaches" hint="A coach takes over that varsity team.">
            <Seg value={p.coach_of || ""} options={[["", "Nothing"], ...TEAMS] as [string, string][]} onChange={(v) => set({ coach_of: v || undefined })} small />
          </Field>
          <Field label="Job title" hint="Shown under their name">
            <input type="text" value={p.role_label || ""} maxLength={40} placeholder={p.coach_of ? `${cap(p.coach_of)} coach` : "History teacher"} onChange={(e) => set({ role_label: e.target.value })} />
          </Field>
        </>
      )}
      {!staff && (
        <Field label="Attracted to" hint="Leave empty to let the generator decide.">
          <div className="chips">
            {([["f", "Girls"], ["m", "Guys"], ["nb", "Nonbinary people"]] as [Gender, string][]).map(([g, l]) => (
              <button key={g} type="button" className={cx("cb-chip", p.attracted_to?.includes(g) && "on")} onClick={() => toggleAttr(g)}>{l}</button>
            ))}
          </div>
        </Field>
      )}
      <Field label="Birthday" hint="Optional">
        <div className="cb-inline">
          <select value={bd[0] || ""} onChange={(e) => set({ birthday: e.target.value ? [Number(e.target.value), bd[1] || 1] : null })}>
            <option value="">Month</option>
            {["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"].map((m, i) => <option key={m} value={i + 1}>{m}</option>)}
          </select>
          <input type="number" min={1} max={31} value={bd[1] || ""} placeholder="Day" disabled={!bd[0]} style={{ width: 76 }}
            onChange={(e) => set({ birthday: [bd[0], clamp(Number(e.target.value) || 1, 1, 31)] })} />
        </div>
      </Field>
      <Field label="Color" wide hint="Their color everywhere in the app.">
        <div className="cb-swatches">
          {COLORS.map((c) => <button key={c} type="button" className={cx("cb-swatch", p.color === c && "on")} style={{ background: c }} onClick={() => set({ color: c })} aria-label={c} />)}
          <label className="cb-swatch custom" title="Pick any color">
            <input type="color" value={p.color || "#9aa1c4"} onChange={(e) => set({ color: e.target.value })} />+
          </label>
        </div>
      </Field>
      <Field label="Bio" wide hint={`${(p.bio || "").length}/500`}>
        <textarea rows={3} maxLength={500} value={p.bio || ""} placeholder={mode === "protagonist" ? "A line or two about you. Optional." : "A line or two about them. Optional."} onChange={(e) => set({ bio: e.target.value })} />
      </Field>
    </div>
  );
}

function topAttrs(a: any) {
  const xs: [string, number][] = [...Object.entries(a.traits || {}), ...Object.entries(a.aptitudes || {})] as any;
  return xs.sort((x, y) => y[1] - x[1]).slice(0, 3);
}

function Start({ p, onChange, cat }: { p: Person; onChange: (p: Person) => void; cat: any }) {
  const anyEdits = ["traits", "aptitudes", "motives", "interests", "skills"].some((l) => Object.keys((p as any)[l] || {}).length);
  return (
    <div className="stack" style={{ gap: 14 }}>
      <div className="cb-arch-grid">
        {cat.archetypes.map((a: any) => (
          <button key={a.id} type="button" className={cx("cb-arch", p.archetype === a.id && "on")} onClick={() => onChange({ ...p, archetype: a.id })}>
            <div className="cb-arch-l">{a.label}</div>
            <div className="cb-arch-b">{ARCH_BLURB[a.id] || ""}</div>
            <div className="cb-arch-t">{topAttrs(a).map(([k, v]) => <span key={k}>{k} {v}</span>)}</div>
          </button>
        ))}
        <button type="button" className={cx("cb-arch", !p.archetype && "on")} onClick={() => onChange({ ...p, archetype: undefined })}>
          <div className="cb-arch-l">Surprise me</div>
          <div className="cb-arch-b">The generator picks a type at random.</div>
        </button>
      </div>
      <div className="row">
        <button type="button" onClick={() => onChange(randomizePerson(cat, p))}>🎲 Randomize around this type</button>
        <button type="button" disabled={!anyEdits} onClick={() => onChange({ ...p, traits: {}, aptitudes: {}, motives: {}, interests: keepSports(p), skills: {} })}>Put everything back on auto</button>
        <span className="hint">Randomize fills personality, talent, drives and interests with believable values. Sports you play are kept.</span>
      </div>
    </div>
  );
}
function keepSports(p: Person) {
  const out: Record<string, number> = {};
  for (const s of SPORTS) if (p.interests?.[s] !== undefined && p.positions?.[s]) out[s] = p.interests[s];
  return out;
}

function SliderSection({ p, onChange, cat, layer, keys }: { p: Person; onChange: (p: Person) => void; cat: any; layer: "traits" | "aptitudes" | "motives"; keys: string[] }) {
  const docs = cat.attributes?.[layer]?.items || {};
  const vals = p[layer] || {};
  const setV = (k: string, v: number | undefined) => {
    const next = { ...vals };
    if (v === undefined) delete next[k];
    else next[k] = v;
    onChange({ ...p, [layer]: next });
  };
  return (
    <div className="stack" style={{ gap: 12 }}>
      <div className="row">
        <button type="button" className="small" onClick={() => onChange(randomizePerson(cat, p, [layer]))}>🎲 Randomize</button>
        <button type="button" className="small" disabled={!Object.keys(vals).length} onClick={() => onChange({ ...p, [layer]: {} })}>Back to auto</button>
        <span className="hint">Faded sliders are on auto (the {archLabel(cat, p.archetype).toLowerCase()} average, with natural variation added when the story is built).</span>
      </div>
      <div className="cb-sliders">
        {keys.map((k) => {
          const v = shown(cat, p, layer, k);
          const auto = vals[k] === undefined;
          return (
            <div key={k} className={cx("cb-sl", auto && "auto")}>
              <div className="cb-sl-h">
                <b>{layer === "aptitudes" ? APT_LABEL[k] : cap(k)}</b>
                <span className="cb-sl-v">{Math.round(v)}</span>
                {auto ? <span className="cb-auto">auto</span> : <button type="button" className="ghost small" title="Back to auto" onClick={() => setV(k, undefined)}>auto</button>}
              </div>
              <input type="range" className="slider" min={0} max={100} step={1} value={v} onChange={(e) => setV(k, Number(e.target.value))} />
              {layer === "traits" && <div className="cb-sl-ends"><span>{TRAIT_WORDS[k][1]}</span><span>{TRAIT_WORDS[k][0]}</span></div>}
              <div className="hint">{docs[k]}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function Interests({ p, onChange, cat }: { p: Person; onChange: (p: Person) => void; cat: any }) {
  const all: [string, string, string][] = [
    ...cat.skills.map((s: any) => [s.id, s.label, "skill"]),
    ...cat.hobbies.map((h: any) => [h.id, cap(h.label), "hobby"]),
  ];
  const ints = p.interests || {};
  const setI = (k: string, v: number | undefined) => {
    const next = { ...ints };
    if (v === undefined) delete next[k];
    else next[k] = v;
    const patch: Partial<Person> = { interests: next };
    if (v === undefined && SPORTS.includes(k) && p.positions?.[k]) {
      const pos = { ...p.positions };
      delete pos[k];
      patch.positions = pos;
    }
    onChange({ ...p, ...patch });
  };
  const skills = p.skills || {};
  const setS = (k: string, v: number | undefined) => {
    const next = { ...skills };
    if (v === undefined) delete next[k];
    else next[k] = v;
    onChange({ ...p, skills: next });
  };
  const chosen = all.filter(([k]) => ints[k] !== undefined);
  return (
    <div className="stack" style={{ gap: 16 }}>
      <div>
        <div className="cb-sub">What they're into <span className="hint">Tap to add. Faded chips are what their type would probably pick up anyway.</span></div>
        <div className="chips">
          {all.map(([k, l]) => {
            const on = ints[k] !== undefined;
            const likely = !on && (shownInterest(cat, p, k) ?? 0) >= 50;
            return (
              <button key={k} type="button" className={cx("cb-chip", on && "on", likely && "likely")} onClick={() => setI(k, on ? undefined : 75)}>
                {on ? "✓ " : "+ "}{l}
              </button>
            );
          })}
        </div>
      </div>
      {chosen.length > 0 && (
        <div className="cb-int-list">
          {chosen.map(([k, l]) => (
            <div key={k} className="cb-int">
              <span>{l}</span>
              <input type="range" className="slider" min={0} max={100} value={ints[k]} onChange={(e) => setI(k, Number(e.target.value))} />
              <span className="cb-sl-v">{Math.round(ints[k])}</span>
              <span className="hint">{ints[k] >= 80 ? "obsessed" : ints[k] >= 60 ? "loves it" : ints[k] >= 40 ? "likes it" : ints[k] >= 20 ? "meh" : "not for them"}</span>
              <button type="button" className="ghost small" onClick={() => setI(k, undefined)} aria-label="remove">×</button>
            </div>
          ))}
        </div>
      )}
      <div>
        <div className="cb-sub">Starting skills <span className="hint">On day one. A typical freshman is 25-50; a standout is 55+. Skills grow with practice up to a ceiling set by talent.</span></div>
        <div className="cb-sliders">
          {cat.skills.map((s: any) => {
            const auto = skills[s.id] === undefined;
            const v = auto ? autoSkill(cat, p, s) : skills[s.id];
            return (
              <div key={s.id} className={cx("cb-sl", auto && "auto")}>
                <div className="cb-sl-h">
                  <b>{s.label}</b>
                  <span className="cb-sl-v">{auto ? "≈" : ""}{Math.round(v)}</span>
                  {auto ? <span className="cb-auto">auto</span> : <button type="button" className="ghost small" title="Back to auto" onClick={() => setS(s.id, undefined)}>auto</button>}
                </div>
                <input type="range" className="slider" min={0} max={90} value={v} onChange={(e) => setS(s.id, Number(e.target.value))} />
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function Athlete({ p, onChange, cat }: { p: Person; onChange: (p: Person) => void; cat: any }) {
  const body = p.body || {};
  const h = body.height_in;
  const setBody = (patch: any) => {
    const next = { ...body, ...patch };
    for (const k of Object.keys(next)) if (next[k] === undefined) delete next[k];
    onChange({ ...p, body: next });
  };
  const defH = p.gender === "f" ? 64 : p.gender === "m" ? 69 : 67;
  const playState = (s: string) => {
    if (p.positions?.[s]) return "yes";
    const iv = p.interests?.[s];
    if (iv === undefined) return "auto";
    return iv >= 40 ? "yes" : "no";
  };
  const setPlay = (s: string, st: string) => {
    const ints = { ...(p.interests || {}) };
    const pos = { ...(p.positions || {}) };
    if (st === "yes") ints[s] = Math.max(ints[s] ?? 0, 80);
    if (st === "no") {
      ints[s] = 10;
      delete pos[s];
    }
    if (st === "auto") {
      delete ints[s];
      delete pos[s];
    }
    onChange({ ...p, interests: ints, positions: pos });
  };
  const setPos = (s: string, v: string | undefined) => {
    const pos = { ...(p.positions || {}) };
    if (v) pos[s] = v;
    else delete pos[s];
    const ints = { ...(p.interests || {}) };
    if (v) ints[s] = Math.max(ints[s] ?? 0, 80);
    onChange({ ...p, positions: pos, interests: ints });
  };
  const setNum = (layer: "interests" | "skills", s: string, v: number | undefined) => {
    const next = { ...(p[layer] || {}) };
    if (v === undefined) delete next[s];
    else next[s] = v;
    onChange({ ...p, [layer]: next });
  };
  return (
    <div className="stack" style={{ gap: 16 }}>
      <div className="cb-body">
        <div className="cb-field">
          <div className="cb-field-l">Height {h ? <b className="cb-big">{heightLabel(h)}</b> : <span className="cb-auto">auto</span>}</div>
          <div className="cb-inline">
            <input type="range" className="slider" min={58} max={84} value={h || defH} onChange={(e) => setBody({ height_in: Number(e.target.value) })} style={{ opacity: h ? 1 : 0.5 }} />
            {h && <button type="button" className="ghost small" onClick={() => setBody({ height_in: undefined })}>auto</button>}
          </div>
          <div className="hint">Height matters most in basketball (every inch over 5'10" helps, more at PF and C) and a little for pitchers. Freshmen still grow a bit.</div>
        </div>
        <div className="cb-field">
          <div className="cb-field-l">Jersey number</div>
          <input type="number" min={0} max={99} value={p.jersey ?? ""} placeholder="auto" style={{ width: 90 }}
            onChange={(e) => onChange({ ...p, jersey: e.target.value === "" ? null : clamp(Math.round(Number(e.target.value)), 0, 99) })} />
        </div>
      </div>
      <div>
        <div className="cb-sub">Build {!body.build && <span className="cb-auto">auto</span>}</div>
        <div className="cb-build-grid">
          {cat.builds.map((b: string) => (
            <button key={b} type="button" className={cx("cb-build", body.build === b && "on")} onClick={() => setBody({ build: body.build === b ? undefined : b })}>
              <b>{cap(b)}</b>
              <span>{BUILD_HINT[b]}</span>
            </button>
          ))}
        </div>
      </div>
      {sportsFor(p.gender).map((s) => {
        const sp = cat.sports[s];
        const st = playState(s);
        const iv = p.interests?.[s];
        const sk = p.skills?.[s];
        return (
          <div key={s} className={cx("cb-sport-card", st === "yes" && "on")}>
            <div className="cb-sport-h">
              <div>
                <b>{sp.label}</b> <span className="hint">{SEASON[sp.season] || sp.season} season · {sp.starters} starters</span>
              </div>
              <Seg small value={st} options={[["yes", "Plays"], ["auto", "Leave to chance"], ["no", "Doesn't play"]]} onChange={(v) => setPlay(s, v)} />
            </div>
            {st === "yes" && (
              <div className="cb-sport-b">
                <div className="cb-int">
                  <span>Love for the game</span>
                  <input type="range" className="slider" min={40} max={100} value={iv ?? 80} onChange={(e) => setNum("interests", s, Number(e.target.value))} />
                  <span className="cb-sl-v">{Math.round(iv ?? 80)}</span>
                  <span />
                  <span />
                </div>
                <div className="cb-int">
                  <span>Skill on day one</span>
                  <input type="range" className="slider" min={0} max={90} value={sk ?? autoSkill(cat, p, { id: s, aptitude: "athletic" })} style={{ opacity: sk === undefined ? 0.5 : 1 }}
                    onChange={(e) => setNum("skills", s, Number(e.target.value))} />
                  <span className="cb-sl-v">{sk === undefined ? "≈" : ""}{Math.round(sk ?? autoSkill(cat, p, { id: s, aptitude: "athletic" }))}</span>
                  <span className="hint">{(sk ?? 0) >= 55 ? "varsity-ready" : (sk ?? 0) >= 40 ? "solid freshman" : sk === undefined ? "auto" : "raw"}</span>
                  {sk !== undefined ? <button type="button" className="ghost small" title="Back to auto" onClick={() => setNum("skills", s, undefined)}>auto</button> : <span />}
                </div>
                <div className="cb-field-l" style={{ marginTop: 6 }}>Position</div>
                <div className="cb-pos-grid">
                  {Object.entries(sp.positions).map(([k, label]: any) => {
                    const fit = body.height_in || body.build ? fitTag(positionFit(s, k, body.height_in || defH, body.build || "average")) : null;
                    return (
                      <button key={k} type="button" className={cx("cb-posb", p.positions?.[s] === k && "on")} onClick={() => setPos(s, k)}>
                        <b>{k}</b>
                        <span>{label}</span>
                        {fit && <i className={`cb-fit-${fit[1]}`}>{fit[0]}</i>}
                      </button>
                    );
                  })}
                  <button type="button" className={cx("cb-posb", !p.positions?.[s] && "on")} onClick={() => setPos(s, undefined)}>
                    <b>?</b>
                    <span>Coach decides</span>
                  </button>
                </div>
              </div>
            )}
            {st === "no" && <div className="hint cb-sport-note">Won't try out. (They could still change their mind years from now.)</div>}
            {st === "auto" && <div className="hint cb-sport-note">Depends on their type and a little luck.</div>}
          </div>
        );
      })}
    </div>
  );
}

function Relationships({ p, set, people, mode }: { p: Person; set: (x: Partial<Person>) => void; people: Target[]; mode: BuilderMode }) {
  const rels = p.relationships || [];
  const X = mode === "protagonist" ? "you" : p.first?.trim() || "They";
  const nameOf = (k: string) => (k === "me" ? "you" : people.find((x) => x.key === k)?.name || k);
  const upd = (i: number, patch: Partial<RelSpec>) => set({ relationships: rels.map((r, j) => (j === i ? { ...r, ...patch } : r)) });
  const used = new Set(rels.map((r) => r.to));
  const free = people.filter((x) => !used.has(x.key));
  const types = REL_TYPES.filter((t) => t !== "sibling" && t !== "twin");
  if (!people.length) {
    return <div className="callout">There's nobody else in the story yet. {mode === "protagonist" ? "Add your family and your people in the next steps, then you can set how they know you from either side." : "Add more people first."}</div>;
  }
  return (
    <div className="stack" style={{ gap: 10 }}>
      {rels.map((r, i) => (
        <div key={i} className="cb-rel-row">
          <div className="cb-rel-top">
            <select value={r.to} onChange={(e) => upd(i, { to: e.target.value })}>
              {people.filter((x) => x.key === r.to || !used.has(x.key)).map((x) => <option key={x.key} value={x.key}>{x.key === "me" ? `You${x.name && x.name !== "You" ? ` (${x.name})` : ""}` : x.name}</option>)}
            </select>
            <select value={r.type} onChange={(e) => upd(i, { type: e.target.value })}>
              {types.map((t) => <option key={t} value={t}>{relOption(t, nameOf(r.to))}</option>)}
            </select>
            <button type="button" className="ghost small" onClick={() => set({ relationships: rels.filter((_, j) => j !== i) })} aria-label="remove">×</button>
          </div>
          <div className="cb-rel-bot">
            <span className="hint">colder</span>
            <input type="range" className="slider" min={-40} max={40} value={r.strength || 0} onChange={(e) => upd(i, { strength: Number(e.target.value) })} />
            <span className="hint">warmer</span>
          </div>
          <div className="cb-rel-say">{relSentence(r.type, X, nameOf(r.to))}{r.strength ? `, ${strengthWords(r.strength)}` : ""}.</div>
        </div>
      ))}
      {free.length > 0 && (
        <div className="row">
          <button type="button" onClick={() => set({ relationships: [...rels, { to: free[0].key, type: "friend" }] })}>+ Add a relationship</button>
          <span className="hint">Anyone not listed starts out however the generator decides (classmates mostly know each other a little).</span>
        </div>
      )}
    </div>
  );
}
